public class DeadlinesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.time.LocalDate d(int y, int m, int day) {
        return java.time.LocalDate.of(y, m, day);
    }

    public static void main(String[] args) {
        check("Mon 03-04 to Fri 03-08", 4, Deadlines.businessDaysUntil(d(2024, 3, 4), d(2024, 3, 8)));
        check("Fri 03-01 to Mon 03-04 (weekend skipped)", 1,
                Deadlines.businessDaysUntil(d(2024, 3, 1), d(2024, 3, 4)));
        check("same day", 0, Deadlines.businessDaysUntil(d(2024, 3, 4), d(2024, 3, 4)));
        check("full week Mon to next Mon", 5, Deadlines.businessDaysUntil(d(2024, 3, 4), d(2024, 3, 11)));
        check("Fri 03-08 to Sun 03-10 (only weekend days)", 0,
                Deadlines.businessDaysUntil(d(2024, 3, 8), d(2024, 3, 10)));
        check("across leap day 2024-02-28 to 2024-03-05", 4,
                Deadlines.businessDaysUntil(d(2024, 2, 28), d(2024, 3, 5)));
        check("to before from", 0, Deadlines.businessDaysUntil(d(2024, 3, 8), d(2024, 3, 4)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

