public class Deadlines {

    public static int businessDaysUntil(java.time.LocalDate from, java.time.LocalDate to) {
        int count = 0;
        java.time.LocalDate day = from.plusDays(1);
        while (!day.isAfter(to)) {
            java.time.DayOfWeek dow = day.getDayOfWeek();
            if (dow != java.time.DayOfWeek.SATURDAY && dow != java.time.DayOfWeek.SUNDAY) {
                count++;
            }
            day = day.plusDays(1);
        }
        return count;
    }
}
